#pragma once
#include <algorithm>
#include <cstddef>
#include <string>
#include <string_view>
#include <vector>

namespace kineticle {
// M1 Arc 1.0.10 accepts at most 2048 bytes per log message. Leave
// room for a build/version/page prefix. Diagnostics generated by Core are ASCII.
inline constexpr std::size_t reportPayloadBytes=1700;
inline std::vector<std::string> reportPages(std::string_view report) {
    std::vector<std::string> pages;
    while(!report.empty()) {
        auto n=std::min(report.size(),reportPayloadBytes);
        if(n<report.size()) {
            const auto boundary=report.substr(0,n).rfind("; ");
            if(boundary!=std::string_view::npos&&boundary>=n/2)n=boundary+2;
        }
        pages.emplace_back(report.substr(0,n));
        report.remove_prefix(n);
    }
    return pages;
}
inline std::string numberedPage(std::string_view version,const std::vector<std::string>& pages,std::size_t i) {
    if(i>=pages.size())return {};
    return std::string(version)+" [diagnostics "+std::to_string(i+1)+"/"+std::to_string(pages.size())+"] "+pages[i];
}
}
